package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class SolidGeometrySvgRenderer { public String render(SolidGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(SolidGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height(),dx=40,dy=23;var b=new StringBuilder("<polygon points=\"").append(p).append(",").append(h-p).append(" ").append(w-p).append(",").append(h-p).append(" ").append(w-p-dx).append(",").append(p+dy).append(" ").append(p+dx).append(",").append(p).append("\" fill=\"none\" stroke=\"#000000\"/>");var occupied=new ArrayList<int[]>();for(var label:s.labels()){String text=label.labelTemplate();var value=values.get(label.valueKey());if(value!=null)text+=" "+value.canonicalValue();int[] pos=new DeterministicLabelLayout().place(p+8,p+18,w,h,Math.max(12,text.length()*7),14,occupied);occupied.add(new int[]{pos[0],pos[1]-14,pos[0]+Math.max(12,text.length()*7),pos[1]});b.append("<text x=\"").append(pos[0]).append("\" y=\"").append(pos[1]).append("\">").append(escape(text)).append("</text>");}return b.toString();}private String escape(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
